fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(4) == 0 {
        host::display::state_set(4, 1);
        host::display::state_set(0, 160);
        host::display::state_set(1, 110);
    }
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(3);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut rw: i32 = host::display::state_get(0);
    let mut rh: i32 = host::display::state_get(1);
    let mut sizing: i32 = host::display::state_get(2);
    let hx: i32 = 40 + rw - 8;
    let hy: i32 = 40 + rh - 8;
    if down == 1 && prev == 0 && px >= hx - 8 && px < hx + 16 && py >= hy - 8 && py < hy + 16 {
        sizing = 1;
    }
    if down == 0 { sizing = 0; }
    if sizing == 1 {
        rw = px - 40;
        rh = py - 40;
        if rw < 40 { rw = 40; }
        if rh < 40 { rh = 40; }
        if rw > w - 80 { rw = w - 80; }
        if rh > h - 100 { rh = h - 100; }
        host::display::state_set(0, rw);
        host::display::state_set(1, rh);
    }
    host::display::state_set(2, sizing);
    host::display::state_set(3, down);
    host::display::clear(0x101010);
    host::display::fill_rect(40, 40, rw, rh, 0x203040);
    host::display::fill_rect(40, 40, rw, 2, 0x6080a0);
    host::display::fill_rect(40, 40 + rh - 2, rw, 2, 0x6080a0);
    host::display::fill_rect(40, 40, 2, rh, 0x6080a0);
    host::display::fill_rect(40 + rw - 2, 40, 2, rh, 0x6080a0);
    let hc: i32 = if sizing == 1 { 0xffffff } else { 0x80a0c0 };
    host::display::fill_rect(hx, hy, 16, 16, hc);
    host::display::draw_number(40, h - 40, rw, 0xffffff, 2);
    host::display::draw_char(96, h - 40, 88, 0x808080, 2);
    host::display::draw_number(114, h - 40, rh, 0xffffff, 2);
    host::display::present();
}
